import{z as n,x as s,o as B,c as d,q as l,j as o,D as E,d as e,s as r,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"城市内部结构","description":"","frontmatter":{"title":"城市内部结构","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ur-intra-city.md","filePath":"econ/ur-intra-city.md","lastUpdated":1791413859000}'),D={name:"econ/ur-intra-city.md"};function p(c,a,h,C,m,u){const t=s("Mermaid");return B(),d("div",null,[a[2]||(a[2]=l('<h1 id="城市内部结构" tabindex="-1">城市内部结构 <a class="header-anchor" href="#城市内部结构" aria-label="Permalink to &quot;城市内部结构&quot;">​</a></h1><div class="epigraph"><p>城市里的租金是通勤的赎金：你少走的那段路，由你多付的房租替你买单；梯度陡不陡，看通勤成本对住房支出的比值。</p><footer>—— 据 Alonso, Location and Land Use, 1964；Mills, An Aggregative Model of Resource Allocation in a Metropolitan Area, 1967；Muth, Cities and Housing, 1969 整理</footer></div><p><a href="/econ/ur-agglomeration">上一课</a>把「为什么聚在一起」写成向心力对离心力的均衡；本课把镜头从城市之间拉近到城市内部：聚起来之后，谁站中心、谁去外围、租金与密度怎么排布。Alonso、Muth 与 Mills 的单中心模型是本课的骨架，后课的住房市场与交通政策都在这副骨架上拧参数。区位竞争的另一支——<a href="/econ/hotelling">Hotelling 线性城市</a>——问厂商为什么扎堆；本课问家庭与企业如何在既有中心周围出价。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>几乎所有城市的房价与人口密度都从中心向外递减，但递减速度差别极大；而且中心住谁并不固定——美国大城市的低收入者常在市中心，另一些城市则是富人在中心、通勤者在边缘。缺口：需要一套能把梯度、密度、谁住哪同时排出来的模型，而不是一组城市轶事。</p><h3 id="出价租与效用拉平" tabindex="-1">出价租与效用拉平 <a class="header-anchor" href="#出价租与效用拉平" aria-label="Permalink to &quot;出价租与效用拉平&quot;">​</a></h3><p>方法是把家庭写成在距离 \\(d\\) 上出价的竞标者：通勤成本 \\(t\\cdot d\\) 随距离上升，住房支出随距离下降；均衡处效用被出价拉平，得到 \\(\\partial p/\\partial d \\lt 0\\) 的出价租曲线，谁出价曲线最陡谁拿中心。企业同理：最依赖面对面可达性的活动出价最高，商业中心落在出价曲线的交点。经验规律是 Clark 1951 的密度梯度 \\(D(d)=D_0\\,e^{-\\lambda d}\\)；Muth 1969 给出 \\(\\lambda\\) 的近似——通勤支出份额与住房支出份额之比，两者都是收入的一到两成，所以梯度天然是「每英里百分之几」的量级，与实测对得上。</p><p><span class="marginnote">美国大都市的密度梯度 \\(\\lambda\\) 在一个世纪里大约降了一半：有轨电车、地铁再到汽车，一路把通勤成本往下压。梯度变平不是住房偏好变了，是 \\(t\\) 变了——用模型读历史的最干净一例（据 Mills 的估算与 Glaeser–Kahn 2001 的整理口径）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>单中心模型的用法是反事实，不是描绘：把通勤成本改一档，梯度、密度、城市边界跟着重排，这正是后课交通投资分析的接口。识别上，区位选择是离散选择问题，与<a href="/econ/discrete-choice">离散选择模型</a>同一语法；把区位属性的价格写成隐含市场，是 Rosen 1974 特征价格的方法，房租梯度里的「可达性价格」是它的特例。辖区维度另算一笔账：Tiebout 1956 说居民按「税收-服务」组合挑选辖区，城市内部的排序因此还要叠一层财政差异，与<a href="/econ/local-fiscal-transfers">地方财政转移</a>相接。</p>',10)),(B(),o(i,null,{default:E(()=>[r(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20CBD%5B%22%E5%8D%95%E4%B8%AD%E5%BF%83%3A%20%E5%8F%AF%E8%BE%BE%E6%80%A7%E6%9C%80%E9%AB%98%E7%9A%84%E7%82%B9%22%5D%20--%3E%20FIRM%5B%22%E4%BC%81%E4%B8%9A%E5%87%BA%E4%BB%B7%3A%20%E9%99%A1%2C%20%E6%8B%BF%E4%B8%AD%E5%BF%83%22%5D%0A%20%20CBD%20--%3E%20HH%5B%22%E5%AE%B6%E5%BA%AD%E5%87%BA%E4%BB%B7%3A%20%E7%BC%93%2C%20%E6%8B%BF%E5%A4%96%E5%9B%B4%22%5D%0A%20%20FIRM%20--%3E%20RENT%5B%22%E7%A7%9F%E9%87%91%E9%9A%8F%E8%B7%9D%E7%A6%BB%E9%80%92%E5%87%8F%22%5D%0A%20%20HH%20--%3E%20RENT%0A%20%20RENT%20--%3E%20DENS%5B%22%E5%AF%86%E5%BA%A6%E6%A2%AF%E5%BA%A6%20D(d)%3DD0*e%5E%7B-lambda*d%7D%22%5D%0A%20%20TC%5B%22%E9%80%9A%E5%8B%A4%E6%88%90%E6%9C%AC%20t%20%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20FLAT%5B%22%E6%A2%AF%E5%BA%A6%E5%8F%98%E5%B9%B3%2C%20%E5%9F%8E%E5%B8%82%E6%91%8A%E5%BC%80%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A("h2",{id:"机制",tabindex:"-1"},[e("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=A("p",null,"梯度变平的机制值得再走一遍：\\(t\\) 下降让外围的「通勤加住房」总成本相对便宜，需求外移，外围密度上升、中心密度下降，就业也随之郊区化（Glaeser 与 Kahn 2001 的就业分散化研究）。单中心因此是基准而不是描述：就业次中心出现时，出价租的逻辑照用，只是出价者多了一组。谁住中心取决于权衡结构而非贫富本身：靠公交的家庭必须贴着线路住，有车的家庭可以把通勤换成外围的便宜房租；把「穷人住市中心」当成普适规律，会把预算约束误读成文化偏好。",-1)),(B(),o(i,null,{default:E(()=>[r(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUD%5B%22%E5%AE%B6%E5%BA%AD%E9%A2%84%E7%AE%97%EF%BC%9A%E4%BD%8F%E6%88%BF%20%2B%20%E9%80%9A%E5%8B%A4%20%2B%20%E5%85%B6%E4%BB%96%E6%B6%88%E8%B4%B9%22%5D%20--%3E%20MODE%7B%22%E4%B8%BB%E8%A6%81%E9%80%9A%E5%8B%A4%E6%96%B9%E5%BC%8F%22%7D%0A%20%20MODE%20--%20%22%E5%85%AC%E4%BA%A4%EF%BC%9At%C2%B7d%20%E9%AB%98%E4%B8%94%E9%9A%BE%E7%BB%95%E5%BC%80%22%20--%3E%20C1%5B%22%E5%BF%85%E9%A1%BB%E8%B4%B4%E7%9D%80%E4%B8%AD%E5%BF%83%E6%88%96%E7%BA%BF%E8%B7%AF%E4%BD%8F%22%5D%0A%20%20MODE%20--%20%22%E6%B1%BD%E8%BD%A6%EF%BC%9At%C2%B7d%20%E4%BD%8E%22%20--%3E%20C2%5B%22%E5%8F%AF%E4%BB%A5%E6%8A%8A%E9%80%9A%E5%8B%A4%E6%8D%A2%E6%88%90%E5%A4%96%E5%9B%B4%E4%BE%BF%E5%AE%9C%E6%88%BF%E7%A7%9F%22%5D%0A%20%20C1%20--%3E%20W1%5B%22%E6%97%A0%E8%BD%A6%E5%AE%B6%E5%BA%AD%E9%9B%86%E4%B8%AD%E5%9C%A8%E5%B8%82%E4%B8%AD%E5%BF%83%22%5D%0A%20%20C2%20--%3E%20W2%5B%22%E6%9C%89%E8%BD%A6%E5%AE%B6%E5%BA%AD%E6%91%8A%E5%90%91%E8%BE%B9%E7%BC%98%22%5D%0A%20%20W1%20--%3E%20OBS%5B%22%E5%90%8C%E4%B8%80%E4%B8%AA%E6%A8%A1%E5%9E%8B%EF%BC%8C%E8%AF%BB%E5%87%BA%E4%B8%A4%E7%B1%BB%E5%9F%8E%E5%B8%82%E7%9A%84%E5%B1%85%E4%BD%8F%E6%8E%92%E5%BA%8F%22%5D%0A%20%20W2%20--%3E%20OBS%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">「出价租」可以想象成一场拍卖：每个家庭给每个位置写一张标书——「住这里，我每月最多肯付多少房租」，房东把位置卖给标价最高的人。同样一套舒适程度，住在近处的标书靠「房租高」压过对手，住远处的靠「通勤便宜」压过对手。</span></p><p><span class="marginnote">数字实例：往外挪一公里，每月房租省 400 元，但通勤多花 200 元——净省 200 元，大家就往外搬；搬的人多了，外围房租被抬回去，直到「房租省的恰好等于通勤多花的」。均衡就停在这个拉平点上，这也解释了为什么梯度天然是「每公里百分之几」的温和斜率。</span></p><p><span class="marginnote">常见误区：「市中心房价高是因为那里的房子更好」。出价租模型的答案是反的：位置本身（可达性）被竞价，房子可以很旧照样贵。另一个误区是把「穷人住市中心」读成文化偏好——很多时候只是没车，预算结构锁住了区位选择。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单中心模型没写供给：住房供给弹性决定需求冲击是涨房价还是盖房子，那是下一课的参数。它也没写聚集：为什么有一个中心、中心会不会迁移，上一课的向心力只给了答案的一半。税制与学区把辖区维度拉进来后，梯度只在同类辖区内部干净。模型对日常生活的解释半径也有限：信息化让部分工作摆脱通勤，但办公室租金照旧陡峭——面对面交换的价值仍写在出价租里，只是它的载体从工厂换成了写字楼。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Alonso–Muth–Mills：出价租竞争排布城市，谁出价曲线陡谁拿中心。</li><li>密度梯度 \\(D(d)=D_0e^{-\\lambda d}\\)，\\(\\lambda\\) 近似为通勤支出份额与住房支出份额之比。</li><li>通勤成本下降让梯度变平、城市摊开；单中心是多中心的基准。</li><li>谁住中心由通勤方式与预算结构决定，不是普适的贫富规律。</li><li>出处：Alonso 1964；Mills 1967；Muth 1969；Clark 1951；Rosen 1974；Tiebout 1956；Glaeser–Kahn 2001。</li></ul>',7))])}const _=n(D,[["render",p]]);export{f as __pageData,_ as default};
